CREATE TABLE IF NOT EXISTS extensions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_id TEXT NOT NULL, repository_id UUID REFERENCES repositories(id) ON DELETE SET NULL, extension_key TEXT NOT NULL, name TEXT NOT NULL, version TEXT NOT NULL, format TEXT NOT NULL, manifest JSONB NOT NULL, enabled BOOLEAN NOT NULL DEFAULT FALSE, status TEXT NOT NULL DEFAULT 'installed', last_error TEXT, source_url TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (owner_id, extension_key))